        ) AS _branch_sku_coercible,
        CASE CASE
            WHEN PG_INPUT_IS_VALID(CAST(financial_status AS TEXT), 'TEXT')
            THEN CAST(financial_status AS TEXT)
          END
          WHEN 'pending'
          THEN 'open'
          WHEN 'paid'
          THEN 'closed'
          WHEN 'refunded'
          THEN 'reversed'
          ELSE CASE
            WHEN PG_INPUT_IS_VALID(CAST(financial_status AS TEXT), 'TEXT')
            THEN CAST(financial_status AS TEXT)
