        CASE
          WHEN PG_INPUT_IS_VALID(
            CAST(CASE
              WHEN SUBSTRING(CAST(created AS VARCHAR) FROM 11) LIKE '%+%'
              OR SUBSTRING(CAST(created AS VARCHAR) FROM 11) LIKE '%-%'
              THEN NULL
              ELSE created
            END AS TEXT),
            'TIMESTAMP'
          )
          AND NOT LOWER(
            CAST(CASE
              WHEN SUBSTRING(CAST(created AS VARCHAR) FROM 11) LIKE '%+%'
              OR SUBSTRING(CAST(created AS VARCHAR) FROM 11) LIKE '%-%'
