SELECT
  *
FROM (
  SELECT
    COUNT(*) AS surviving_rows,
    SUM(
      CASE
        WHEN COALESCE(
          (
            _survivors._branch_gift_note_coercible
            OR _survivors._branch_order_id_coercible
            OR _survivors._branch_quantity_coercible
            OR _survivors._branch_sku_coercible
            OR _survivors._branch_status_coercible
            OR _survivors._branch_status_in_enum
          ),
          FALSE
        )
        THEN 1
        ELSE 0
      END
    ) AS diverted_rows,
    (
      SELECT
        COUNT(*)
      FROM bronze.shopify__order_lines
    ) + (
      SELECT
        COUNT(*)
      FROM bronze.woo__order_lines
    ) AS bronze_rows,
    (
      SELECT
        COUNT(*)
      FROM @this_model AS _entity
      WHERE
        (_entity._source, _entity._source_row_id) IN (
          SELECT
            _source,
            _source_row_id
          FROM _survivors
        )
    ) AS entity_rows
  FROM _survivors
) AS _conservation
WHERE
  entity_rows + diverted_rows <> surviving_rows
